// Builds supabase/release/20261030/03_apply.sql: every pending migration this
// release needs, unchanged, in application order, in one transaction (all or
// nothing). Run: node scripts/care-release-bundle.mjs  (then `--check` in CI).
import { readFileSync, writeFileSync } from 'node:fs'
export const ORDER = [
  'supabase/pending/pricing-and-payments/20261102_pricing_titles_and_payment_schedule.sql',
  'supabase/pending/website-care/20261030_website_care.sql',
  'supabase/pending/website-care/20261031_care_work_ledger.sql',
  'supabase/pending/website-care/20261103_care_report_suggestions.sql',
  'supabase/pending/website-care/20261104_care_checkout_invitations.sql',
  'supabase/pending/website-care/20261105_care_agreements_and_dispatch.sql',
  'supabase/pending/website-care/20261106_care_agreement_links.sql',
  'supabase/pending/website-care/20261107_care_function_search_path.sql',
]
const root = new URL('..', import.meta.url).pathname
let out = `-- GENERATED by scripts/care-release-bundle.mjs. Do not edit; edit the source files.
-- Website Care release (Oct 30, 2026): the reviewed pending migrations, unchanged,
-- in application order, in ONE transaction. If any statement fails, nothing is
-- applied. Run 01_precheck.sql and 02_backup.sql first, 04_verify.sql after.
begin;
`
for (const f of ORDER) out += `\n-- ==================================================================\n-- ${f}\n-- ==================================================================\n${readFileSync(root + f, 'utf8').replace(/^\s*notify pgrst, 'reload schema';\s*$/gm, '')}\n`
out += `\ncommit;\nnotify pgrst, 'reload schema';\n`
const target = root + 'supabase/release/20261030/03_apply.sql'
if (import.meta.url !== `file://${process.argv[1]}`) { /* imported for ORDER only */ } else if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== out) { console.error('03_apply.sql is out of date; run node scripts/care-release-bundle.mjs'); process.exit(1) }
  console.log('03_apply.sql matches the pending migrations.')
} else { writeFileSync(target, out); console.log('wrote', target) }
